8	/**
9	 * The single duplicate check for create-owner, now keyed on the household. The household is keyed
10	 * on {@code (lastName, postcode)} via the deterministic {@link Household#id(Owner) householdId}, so
11	 * a second owner sharing a last name and postcode is the same household: it is rejected with a 409
12	 * Conflict UNLESS the request opted in with {@code sharesHousehold} true, in which case it is
13	 * created as a declared household member. Runs after {@link AssignOwnerHousehold} has stamped the
14	 * householdId.
15	 */
16	public class CheckOwnerIdentityUnique {
17	
18	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        if (Boolean.TRUE.equals(sharesHousehold)) {
21	            return; // opted in as a declared household member: bypass the duplicate block
22	        }
23	        String householdId = owner.getHouseholdId();
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
26	                continue; // same record (e.g. re-save), not a conflict
27	            }
28	            if (householdId != null && householdId.equals(Household.id(existing))) {
29	                throw new DuplicateIdentityException(householdId);
30	            }
31	        }
32	    }
33	}
